<?php
require_once 'auth.php'; require_admin(); require_once 'db.php';
$student_id=strtoupper(trim($_GET['student_id']??''));$year=(string)($_GET['year']??'');$semester=(string)($_GET['semester']??'');$detail=($student_id!==''&&$year!==''&&$semester!=='');
$student=null;$rows=[];$message='';$summary=['gpa'=>0,'class'=>'Fail','credits'=>0];
if($detail){
 if(!valid_student_id($student_id)||!valid_year_semester($year,$semester))$message='Invalid Student ID, Year or Semester.';
 else{$s=mysqli_prepare($conn,'SELECT * FROM students WHERE student_id=? LIMIT 1');mysqli_stmt_bind_param($s,'s',$student_id);mysqli_stmt_execute($s);$student=mysqli_fetch_assoc(mysqli_stmt_get_result($s));if(!$student)$message='Student ID not found.';else{$r=mysqli_prepare($conn,'SELECT * FROM results WHERE student_id=? AND year=? AND semester=? ORDER BY subject_code');mysqli_stmt_bind_param($r,'sss',$student_id,$year,$semester);mysqli_stmt_execute($r);$rr=mysqli_stmt_get_result($r);while($x=mysqli_fetch_assoc($rr))$rows[]=$x;$summary=calculate_gpa_summary(array_values(array_filter($rows,fn($r)=>($r['publish_status']??'draft')==='published' && ($r['approval_status']??'pending')==='approved')));}}
}else{
 $q=trim($_GET['q']??'');$status=$_GET['status']??'all';$fy=(string)($_GET['fy']??'');$fs=(string)($_GET['fs']??'');$page=safe_page_int($_GET['page']??1);$per=30;$where=[];$params=[];$types='';
 if($q!==''){$where[]='(r.student_id LIKE ? OR s.name LIKE ? OR s.index_number LIKE ? OR r.subject_code LIKE ? OR r.subject LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like,$like,$like);$types.='sssss';}
 if(valid_result_status($status)){$where[]='r.publish_status=?';$params[]=$status;$types.='s';}
 if(in_array($fy,['1','2','3','4'],true)){$where[]='r.year=?';$params[]=$fy;$types.='s';}
 if(in_array($fs,['1','2'],true)){$where[]='r.semester=?';$params[]=$fs;$types.='s';}
 $w=$where?' WHERE '.implode(' AND ',$where):'';$c=mysqli_prepare($conn,'SELECT COUNT(*) c FROM results r JOIN students s ON s.student_id=r.student_id'.$w);if($params)mysqli_stmt_bind_param($c,$types,...$params);mysqli_stmt_execute($c);$total=(int)(mysqli_fetch_assoc(mysqli_stmt_get_result($c))['c']??0);$pages=max(1,(int)ceil($total/$per));$page=min($page,$pages);$offset=($page-1)*$per;$sql='SELECT r.*,s.name,s.index_number FROM results r JOIN students s ON s.student_id=r.student_id'.$w.' ORDER BY r.id DESC LIMIT '.$per.' OFFSET '.$offset;$st=mysqli_prepare($conn,$sql);if($params)mysqli_stmt_bind_param($st,$types,...$params);mysqli_stmt_execute($st);$rs=mysqli_stmt_get_result($st);while($x=mysqli_fetch_assoc($rs))$rows[]=$x;
}
?><!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Results</title><link rel="icon" href="favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="modern-ui.css?v=20261006-modern2"></head><body><div class="main-wrapper"><?php include 'admin_nav.php';?><main class="content"><section class="page-heading"><div><span class="page-kicker">Academic Records</span><h1><?= $detail?'Semester Results':'Results' ?></h1><p><?= $detail?'Review, edit and publish this student semester.':'Search and paginate across result records.' ?></p></div></section>
<?php if(!$detail):?><section class="feature-card"><form method="get"><div class="form-grid-3"><div><label>Search</label><input name="q" value="<?=e($q)?>" placeholder="Student, index, subject"></div><div><label>Status</label><select name="status"><option value="all">All</option><?php foreach(['draft','published','withheld'] as $x):?><option value="<?=$x?>" <?=$status===$x?'selected':''?>><?=e(result_status_label($x))?></option><?php endforeach;?></select></div><div><label>Year</label><select name="fy"><option value="">All Years</option><?php for($i=1;$i<=4;$i++):?><option value="<?=$i?>" <?=$fy===(string)$i?'selected':''?>>Year <?=$i?></option><?php endfor;?></select></div></div><label>Semester</label><select name="fs"><option value="">All Semesters</option><option value="1" <?=$fs==='1'?'selected':''?>>Semester 1</option><option value="2" <?=$fs==='2'?'selected':''?>>Semester 2</option></select><div class="button-row"><a class="btn-link btn-secondary" href="view_results.php">Clear</a><input type="submit" value="Search"></div></form></section><section class="feature-card wide-card"><div class="table-wrapper"><table class="results-table"><tr><th>Student</th><th>Term</th><th>Subject</th><th>Marks</th><th>Grade</th><th>Approval</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><strong><?=e($r['student_id'])?></strong><br><small><?=e($r['name'])?> · <?=e($r['index_number'])?></small></td><td>Y<?=e($r['year'])?> S<?=e($r['semester'])?></td><td><?=e($r['subject_code'])?><br><small><?=e($r['subject'])?><br><?=e(result_attempt_label($r))?></small></td><td><?=e($r['marks'])?></td><td><?=e($r['grade'])?></td><td><span class="status-pill <?=e($r['approval_status']??'pending')?>"><?=e(approval_status_label($r['approval_status']??'pending'))?></span></td><td><span class="status-pill <?=e($r['publish_status'])?>"><?=e(result_status_label($r['publish_status']))?></span></td><td><a class="btn-link small-btn" href="view_results.php?student_id=<?=urlencode($r['student_id'])?>&year=<?=urlencode($r['year'])?>&semester=<?=urlencode($r['semester'])?>">Open Term</a></td></tr><?php endforeach;?></table></div><div class="pagination"><?php for($i=max(1,$page-2);$i<=min($pages,$page+2);$i++):?><a class="filter-chip" href="?<?=http_build_query(array_merge($_GET,['page'=>$i]))?>"><?=$i?></a><?php endfor;?></div></section>
<?php else:?><?php if($message):?><div class="message error"><?=e($message)?></div><?php elseif(!$rows):?><div class="message error">No results found for this semester.</div><?php else:?><section class="feature-card"><div class="student-info"><strong><?=e($student['name'])?></strong> · <?=e($student_id)?> · <?=e($student['index_number'])?></div><div class="gpa-summary"><strong>Published Semester GPA:</strong> <?=gpa_display($summary)?> &nbsp; | &nbsp; <strong>Class:</strong> <?=e($summary['class'])?></div></section><section class="feature-card wide-card"><div class="table-wrapper"><table class="results-table"><tr><th>#</th><th>Subject</th><th>Code</th><th>Marks</th><th>Grade</th><th>GPA</th><th>Approval</th><th>Status</th><th>Actions</th></tr><?php foreach($rows as $i=>$row):?><tr><td><?=$i+1?></td><td><?=e($row['subject'])?><br><small><?=e(result_attempt_label($row))?><?=((int)$row['includes_gpa']?'':' · Non-GPA')?></small></td><td><?=e($row['subject_code'])?></td><td><?=e($row['marks'])?></td><td><?=e($row['grade'])?></td><td><?=result_gpa_display($row)?></td><td><span class="status-pill <?=e($row['approval_status']??'pending')?>"><?=e(approval_status_label($row['approval_status']??'pending'))?></span></td><td><span class="status-pill <?=e($row['publish_status'])?>"><?=e(result_status_label($row['publish_status']))?></span></td><td class="actions-cell"><?php if(!result_is_protected($row) && has_role(['super_admin','data_entry'])):?><a class="btn-link small-btn" href="edit_result.php?id=<?=(int)$row['id']?>">Edit</a><form class="inline-form" method="post" action="delete_result.php" onsubmit="return confirm('Delete this result?');"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$row['id']?>"><input type="hidden" name="student_id" value="<?=e($student_id)?>"><input type="hidden" name="year" value="<?=e($year)?>"><input type="hidden" name="semester" value="<?=e($semester)?>"><button class="btn-danger small-btn" type="submit">Delete</button></form><?php elseif(result_is_protected($row) && has_role(['super_admin','registrar'])):?><a class="btn-link small-btn" href="reopen_result.php?id=<?=(int)$row['id']?>">Reopen</a><?php else:?><span class="status-pill">Read only</span><?php endif;?></td></tr><?php endforeach;?></table></div></section><?php endif;?><div class="button-row"><a href="view_results.php" class="btn-link btn-secondary">Back to Results</a></div><?php endif;?></main><?php include 'footer.php';?></div></body></html>
